INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62568270', 62568270, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Pemeliharaan UPS', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 529000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 18 Unit, @Rp 29.389)', '1. Pemeliharaan UPS ( 18 Unit, @Rp 29.389)', 'Nama Paket : Pemeliharaan UPS (Uninterruptible Power Supply) Volume : 18 Unit/Tahun Harga Satuan : @ Rp29.389 ________________________________________ 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pemeliharaan rutin dan perbaikan ringan pada seluruh unit UPS di lingkungan kantor selama periode 1 (satu) tahun untuk memastikan pasokan listrik cadangan tetap handal dan aman digunakan. ________________________________________ 2. Spesifikasi Teknis 1. Pemeliharaan mencakup: o Pembersihan UPS dan area ventilasi dari debu. o Pemeriksaan kondisi baterai, koneksi, dan kabel penghubung. o Uji fungsional UPS untuk memastikan suplai listrik cadangan bekerja dengan baik. o Perbaikan ringan akibat pemakaian normal (misal penggantian fuse, kabel, atau indikator). 2. Pemeliharaan dilakukan secara berkala sesuai jadwal atau kebutuhan teknis. 3. Penggantian komponen minor menggunakan suku cadang asli atau setara yang memenuhi standar pabrikan. 4. Setiap kegiatan pemeliharaan dicatat dalam buku servis atau laporan resmi. ________________________________________ 3. Persyaratan 1. Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. 2. Harga sudah termasuk biaya jasa, suku cadang, dan pajak. 3. Penyedia bertanggung jawab atas kelancaran, kualitas, dan keamanan pemeliharaan UPS. 4. Apabila pemeliharaan tidak dilakukan sesuai ketentuan atau menimbulkan kerusakan baru, penyedia wajib melakukan perbaikan atau penggantian tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 651481);
