INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63135817', 63135817, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Penyusunan Dokumen Sistem Manajemen Keamanan Informasi (SMKI) Direktorat Jenderal Perkeretaapian', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1000000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Maksud dari kegiatan ini yaitu menerapkan Sistem Manajemen Keamanan Informasi (SMKI) secara optimal dan upaya peningkatan keamanan informasi lainnya di lingkungan Direktorat Jenderal Perkeretaapian guna memastikan bahwa informasi dan sistem yang digunakan terlindungi dengan baik dari ancaman keamanan termasuk menyediakan panduan dalam mengidentifikasi risiko dan mengambil tindakan yang tepat untuk meminimalkan risiko tersebut. Selain itu, SMKI juga digunakan sebagai alat untuk memastikan kepatuhan terhadap peraturan dan standar keamanan yang berlaku. Tujuan dari penyusunan dokumen SMKI Direktorat Jenderal Perkeretaapian adalah : 1. Meminimalkan risiko keamanan informasi melalui identifikasi risiko keamanan informasi dan menentukan tindakan yang tepat untuk meminimalkan risiko tersebut. Dengan demikian, Direktorat Jendral Perkeretaapian dapat mengurangi kemungkinan terjadinya kerugian akibat kehilangan atau penggunaan data yang tidak sah. 2. Mengoptimalkan penggunaan sumber daya yang tersedia untuk menjaga keamanan informasi. Dengan memiliki strategi yang jelas dan terstruktur dalam dokumen SMKI termasuk Business Continuity Plan (BCP), Direktorat Jenderal Perkertaapian dapat menghindari pengeluaran yang tidak perlu untuk keamanan informasi. 3. Membantu organisasi untuk menjaga kelangsungan bisnis dalam situasi yang tidak terduga, seperti bencana alam atau insiden keamanan. Dengan memiliki rencana darurat yang terdokumentasi dalam dokumen SMKI dan dokumen BCP, Direktorat Jenderal Perkeretaapian dapat merespons situasi tersebut dengan cepat dan efektif, sehingga bisnis dapat berjalan kembali secepat mungkin', 'Lingkup kegiatan penyusunan dokumen SMKI meliputi : 1. Melakukan evaluasi menyeluruh terhadap sistem keamanan siber di lingkungan Direktorat Jenderal Perkeretaapian yang digunakan mencakup perangkat keras dan lunak, jaringan serta prosedur operasional. 2. Inventarisasi dan klasifikasi aset teknologi informasi termasuk pengolahan informasi yang dimiliki, digunakan dan/atau dikelola di lingkungan Direktorat Jenderal Perkeretaapian. 3. Melakukan proses risk assessment (identifikasi, analisis dan evaluasi risiko) terkait keamanan informasi dan potensi ancaman di lingkungan Direktorat Jenderal Perkeretaapian termasuk identifikasi dan implementasi kontrol keamanan informasi dalam pengelolaannya. 4. Melaksanakan penetration testing pada modul layanan di lingkungan Direktorat Jenderal Perkeretaapian untuk mengidentifikasi, mengeksploitasi, dan mengevaluasi kelemahan atau celah keamanan yang ada pada modul layanan untuk selanjutnya difasilitasi/ditindaklanjuti terhadap temuan penetration testing tersebut. 5. Melaksanakan evaluasi dan/atau audit internal penerapan Kebijakan dan Standar SMKI di lingkungan Direktorat Jenderal Perkeretaapian. 6. Menyusun dokumen Sistem Manajemen Keamanan Informasi (SMKI) dan dokumen Business Continuity Plan (BCP) termasuk tata kelola, strategi pemulihan dan penyusunan/pembaharuan prosedur peningkatan keamanan informasi sesuai ketentuan di lingkungan Kementerian Perhubungan. 7. Melaksanakan pelatihan dan sosialisasi kepada pegawai di Lingkungan Direktorat Jenderal Perkeretaapian tentang kebijakan dan upaya peningkatan keamanan informasi termasuk pembuatan dokumentasi/multimedia dalam upaya meningkatkan kesadaran dan tanggung jawab setiap individu dalam menjaga keamanan informasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 658938);
