INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63135518', 63135518, 'analyze_legacy', 'Kab. Pasuruan', 'kabkota', 'DINAS KOMUNIKASI DAN INFORMATIKA', 'Layanan Internet Dedicated 1000 Mbps DC Utama', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Pasuruan (Kab.)', 725040000, 'January 2026', 'APBD', 1, 1, '12 Bulan', 'Pekerjaan ini adalah pengadaan layanan internet utama berkecepatan sangat tinggi untuk Dinas Komunikasi dan Informatika (Diskominfo) Kabupaten Pasuruan. Spesifikasi Utama: Nama Barang/Jasa: Layanan Internet Dedicated. Kapasitas: 1.000 Mbps (1 Gbps) untuk koneksi ke Data Center (DC). Rincian Bandwidth: Domestik: 1000 Mbps (untuk akses dalam negeri). Internasional: 500 Mbps (untuk akses ke luar negeri). Jenis Layanan: Dedicated (jalur internet eksklusif yang tidak dibagi dengan pengguna lain, menjamin kecepatan penuh dan stabil). Tujuan: Menyediakan jalur internet inti yang andal, berkecepatan tinggi, dan berkapasitas besar untuk mendukung operasional dan pelayanan publik Diskominfo Kabupaten Pasuruan, seperti: Infrastruktur TIK pemerintah (e-government). Layanan data dan komunikasi yang membutuhkan bandwidth besar. Koneksi yang stabil dan aman untuk pusat data. Intinya: Membeli koneksi internet khusus yang super cepat dan terbagi untuk domestik & internasional sebagai tulang punggung jaringan pemerintah daerah.', '1. Minimum 1000Mbps Bandwidth Internet Dedicated Domestik dengan rasio 1:1 include Minimum bandwidth dedicated International 500 Mbps. 2. Bandwith ratio CIR (Committed Information Rate) 1:1 upstream dan downstream (Clear Channel). 3. Akses ke IIX tidak lebih dari 3 HOP. 4. SLA min 99.9%. 5. Akses ke IIX tidak lebih dari 3 HOP 6. Mendapatkan perawatan, dukungan dan pelayanan 24x7 onsite (Lokasi di Kota/ Kabupaten Pasuruan). 7. Menyediakan Link Network dan Manage Service Free Colocation min 4U atau menyediakan Cloud untuk DRC dengan ketentuan lokasi DRC /data ada di Indonesia) 8. Free Fasilitas Pengamanan Jaringan (anti DDos, antivirus dan antispam). Add on Pekerjaan: a. Upgrade Akses ke IIX ke 2 HOP dan 2 InterKoneksi: 1) BGP Ruang Server Kominfo  IIX Gedung Cyber Jakarta (2 HOP) dan; 2) BGP Ruang Server Kominfo  IIX Telkom Surabaya (2 HOP) b. Penarikan Jalur FO 12 Core rute Kantor Kecamatan Gondang Wetan  Kantor Kecamatan Winongan ( + 5KM). c. Bantuan Teknisi untuk Pemeliharaan Jaringan Internal Komplek Perkantoran Raci selama 1 tahun.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 659104);
